/* From Uiverse.io by ArturCodeCraft - Tags: button, links, btn */
/* <reset-style> ============================ */
.__UIV_SCOPE__ a {
  text-decoration: none;
}
/* <main-style> ============================ */
.__UIV_SCOPE__ .menu__link {
  color: #fff;
  line-height: 2;
  position: relative;
  padding-right: 4px;
}

.__UIV_SCOPE__ .menu__link:hover {
  text-decoration: underline;
}

.__UIV_SCOPE__ .menu__link::before {
  content: '';
  width: 6px;
  height: 6px;
  border-top: solid 2px #fff;
  border-right: solid 2px #fff;
  border-radius: 2px;
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%) rotate(45deg);
}
